    xs i prim seq-int.len locals { len } {
      i len prim < [
        xs i prim seq-int.at locals { val } {
          val acc prim + locals { new-acc } {
            xs i 1 prim + new-acc sum-helper
          }
        }
      ] [
        acc
      ] if
    }
  };

: main
  (forall ρ; ρ xs:Seq Int^many -- ρ result:Int^many)
  locals { xs } { xs 0 0 sum-helper };

