    xs i prim seq-int.len locals { len } {
      i 1 prim - locals { prev-i } {
        prev-i len prim < [
          xs prev-i prim seq-int.at locals { prev } {
            xs i prim seq-int.at locals { curr } {
              prev curr prim < [
                false
              ] [
                xs i 1 prim + is-sorted-helper
              ] if
            }
          }
        ] [
          true
